var t=[{title:`Wat de patronen beschrijven`,text:`Een squat buigt en strekt vooral de heupen, knieën en enkels samen. Een heupscharnier beweegt vooral in de heupen, terwijl lunges en step-ups één been tegelijk belasten. Duwen beweegt weerstand van het lichaam af en trekken brengt die naar het lichaam toe. Bij een carry houd je een gewicht stabiel terwijl je loopt, coreoefeningen weerstaan of produceren rompbeweging, en voortbewegen omvat wandelen, rennen en vergelijkbare beweging.`},{title:`Waarom patronen ertoe doen`,text:`Eén oefening kan meerdere spieren en patronen tegelijk trainen. Een goblet squat traint de benen en de romp, en een beladen carry traint grip, houding en loopmechanica. Oefeningen sorteren op patroon laat gaten zien die een lijst die alleen op borst, armen en benen is gesorteerd kan missen. Je hebt niet elk patroon in elke training nodig.`},{title:`Een evenwichtige week opbouwen`,text:`Verspreid over twee of drie full-body-sessies kan een beginner een squat, een heupscharnier, een horizontale duw, een horizontale trek, een lunge en een eenvoudige anti-rotatie- of anti-extensieoefening opnemen. Verticaal duwen, verticaal trekken en carries kunnen erbij komen als je uitrusting, mobiliteit en doelen het toelaten. Houd de dosis voor elk patroon klein genoeg om van te herstellen en sla oefeningen over die je niet nodig hebt.`},{title:`Patronen afstemmen op vermogen`,text:`Elk patroon heeft makkelijkere en moeilijkere varianten. Een stoelsquat kan voor een goblet squat komen, en een push-up tegen de muur voor een push-up op de vloer. Een kabelroeibeweging en een dumbbellroeibeweging zijn allebei horizontale trekbewegingen, maar ze vragen verschillende balans en uitrusting. Als een beweging ongemak geeft of instabiel aanvoelt, verander dan de variant en houd het patroon.`},{title:`TrainUp gebruiken`,text:`Elke oefeningpagina bij Oefeningen toont het bewegingspatroon, zodat je kunt checken hoe je geplande week ze dekt. Als de meeste sessies duwen bevatten en bijna geen trekken, vult een roei- of pulldownoefening die bij je uitrusting en beperkingen past het gat. Streef naar goede dekking over weken, niet naar een perfecte verhouding in elke sessie.`}];var i=[{label:`NSCA: basis van veiligheid en krachttraining`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};